import{_ as s,o as i,c as e,a5 as t}from"./chunks/framework.a5no_H3L.js";const o=JSON.parse('{"title":"订单状态流转","description":"订单从创建到完结要经过一串状态，待支付、已支付、已发货、已完成。状态不能乱跳，已支付的订单不能再变成待支付，已取消的订单不能被重复取消。本章只回答一个问题，怎么保证状态只在合法路径上流转，且并发下不会跳错。","frontmatter":{},"headers":[],"relativePath":"scenarios/05-cases/chapter-03-order-state-machine.md","filePath":"scenarios/05-cases/chapter-03-order-state-machine.md"}'),n={name:"scenarios/05-cases/chapter-03-order-state-machine.md"};function r(h,a,p,l,c,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="订单状态流转" tabindex="-1" data-src-line="1" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">订单状态流转 <a class="header-anchor" href="#订单状态流转" aria-label="Permalink to &quot;订单状态流转&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md"><p data-src-line="3" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">订单从创建到完结要经过一串状态，待支付、已支付、已发货、已完成。状态不能乱跳，已支付的订单不能再变成待支付，已取消的订单不能被重复取消。本章只回答一个问题，怎么保证状态只在合法路径上流转，且并发下不会跳错。</p></blockquote><h2 id="_1-状态不能乱跳" tabindex="-1" data-src-line="5" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">1. 状态不能乱跳 <a class="header-anchor" href="#_1-状态不能乱跳" aria-label="Permalink to &quot;1. 状态不能乱跳&quot;">​</a></h2><p data-src-line="7" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">订单状态是一条有向路径，不是随便改的字段。</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PENDING ──→ PAID ──→ SHIPPING ──→ COMPLETED</span></span>
<span class="line"><span>   │                      │</span></span>
<span class="line"><span>   ↓                      ↓</span></span>
<span class="line"><span>CANCELLED            REFUNDING ──→ REFUNDED</span></span></code></pre></div><p data-src-line="16" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">待支付只能变成已支付或已取消，已支付只能变成已发货或退款中。每个状态有固定的出口，越过出口就是脏数据。</p><p data-src-line="18" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">朴素的写法是查出来改状态，先查出订单当前状态，判断要跳的目标合不合法，合法再更新。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Order order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orderMapper.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">selectById</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(orderId);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PENDING&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">equals</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(order.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getStatus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    orderMapper.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">updateStatus</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(orderId, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PAID&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p data-src-line="27" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">这段代码在并发下会出问题。两个请求同时读到 <code>PENDING</code>，都判断合法，各自把状态改成 <code>PAID</code>。改成已支付还不致命，改成别的就可能重复扣款、重复发货。问题的根源和库存扣减一样，「判断」和「更新」之间插入了另一个请求。</p><h2 id="_2-条件更新-让状态机在数据库里生效" tabindex="-1" data-src-line="29" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">2. 条件更新，让状态机在数据库里生效 <a class="header-anchor" href="#_2-条件更新-让状态机在数据库里生效" aria-label="Permalink to &quot;2. 条件更新，让状态机在数据库里生效&quot;">​</a></h2><p data-src-line="31" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">修法和乐观锁思路一致。把「当前状态是 PENDING」写进 UPDATE 的 WHERE 条件，判断和更新合成一条原子语句。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t_order</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;PAID&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, paid_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> now</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> order_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ? </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;PENDING&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p data-src-line="39" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md"><code>status = &#39;PENDING&#39;</code> 就是这条状态流转的守卫。只有当前确实是待支付，这条更新才生效。返回受影响行数为 0，说明状态已经被别的请求改掉了，这次流转不合法，直接返回失败，不重试。</p><p data-src-line="41" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">这一步把状态机的合法性从应用代码下沉到了数据库。应用层不用再先查再判断，一条带条件的更新同时完成了「检查状态」和「改变状态」。</p><h2 id="_3-幂等靠的就是这条守卫" tabindex="-1" data-src-line="43" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">3. 幂等靠的就是这条守卫 <a class="header-anchor" href="#_3-幂等靠的就是这条守卫" aria-label="Permalink to &quot;3. 幂等靠的就是这条守卫&quot;">​</a></h2><p data-src-line="45" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">状态机的守卫天然带来幂等。超时取消这个场景最能说明问题。</p><p data-src-line="47" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">订单超时后，延迟队列发来一条取消消息。正常情况下这条消息只发一次，但消息队列是 at-least-once，可能重投。取消逻辑写成条件更新：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> t_order </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;CANCELLED&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> order_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ? </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;PENDING&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p data-src-line="54" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">第一次收到消息，订单是待支付，更新生效，返回 1，接着回补库存。第二条重复消息到达时，订单已经是已取消，<code>status = &#39;PENDING&#39;</code> 不成立，返回 0，直接跳过，不会重复回补库存。</p><p data-src-line="56" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">这条守卫就是幂等性设计里的状态机守卫，一种乐观锁式的条件更新。状态机守卫和乐观锁版本号、唯一约束、Token、去重表的关系与选型，见 <a href="./../02-concurrency/chapter-03-idempotency.html">幂等性设计</a>。同一个订单从待支付到已取消只能发生一次，第二次自然失效。</p><h2 id="_4-什么状态能跳-表驱动还是条件更新" tabindex="-1" data-src-line="58" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">4. 什么状态能跳，表驱动还是条件更新 <a class="header-anchor" href="#_4-什么状态能跳-表驱动还是条件更新" aria-label="Permalink to &quot;4. 什么状态能跳，表驱动还是条件更新&quot;">​</a></h2><p data-src-line="60" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">状态多了之后，合法流转关系怎么维护。两种做法。</p><p data-src-line="62" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">条件更新在每个入口写死 <code>WHERE status = ?</code>，适合状态少、流转简单的场景。状态一多，每个入口的守卫条件散落在各处的 SQL 里，改一处漏一处。</p><p data-src-line="64" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">更复杂的做法是维护一张状态机表，记录每个状态允许跳向哪些状态，更新前先查表校验。代价是多一次查询，而且查表和更新之间又回到了「判断」和「更新」分离的老问题，还得配合锁或条件更新兜底。</p><p data-src-line="66" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">结论是，条件更新是底线，无论状态机多复杂，最终都要落到一条带守卫条件的原子更新上。状态机表只是辅助组织流转关系，不能替代守卫条件。</p><h2 id="_5-相关章节" tabindex="-1" data-src-line="68" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">5. 相关章节 <a class="header-anchor" href="#_5-相关章节" aria-label="Permalink to &quot;5. 相关章节&quot;">​</a></h2><p data-src-line="70" data-src-file="scenarios/05-cases/chapter-03-order-state-machine.md">状态流转依赖延迟队列把超时消息准时投递出来，见 <a href="./../03-messaging/chapter-01-delayed-task.html">延迟队列</a>。消息重复投递的完整解法见 <a href="./../03-messaging/chapter-03-deduplication.html">消息去重</a>，订单支付状态与回调、退款和对账的联动见 <a href="./chapter-08-payment-reconciliation.html">支付回调与对账</a>。库存回补的动作属于库存扣减的逆过程，见 <a href="./chapter-01-inventory-deduction.html">库存扣减并发控制</a>。</p>`,27)])])}const E=s(n,[["render",r]]);export{o as __pageData,E as default};
